// Some portions generated by Claude
'use strict';
const test = require('node:test');
const assert = require('node:assert/strict');
const workspace = require(require('./workbench-scripts.js').workbenchScriptPath('workbenchWorkspace.js'));

const SERVER = 'sha256:' + 'a'.repeat(64);

function shell(attributes) {
    const app = { getAttribute: (name) => (name in attributes ? attributes[name] : null) };
    return { getElementById: (id) => (id === 'workbench-app' ? app : null) };
}

test('a scope is the server digest, the user and the repository, the same in every browser session', () => {
    const first = workspace.scopeOf(SERVER + ':11111111-1111-4111-8111-111111111111', '', 'lmdb');
    const later = workspace.scopeOf(SERVER + ':22222222-2222-4222-8222-222222222222', '', 'lmdb');
    assert.deepEqual(first, { digest: SERVER, user: '', repositoryId: 'lmdb' });
    assert.ok(workspace.sameScope(first, later), 'a new browser session finds the same state');
    assert.ok(!workspace.sameScope(first, workspace.scopeOf(SERVER, 'ada', 'lmdb')), 'each user has their own');
    assert.equal(workspace.scopeOf('', '', 'lmdb'), null, 'no server, no scope');
    assert.equal(workspace.scopeOf(SERVER, '', ''), null, 'no repository, no scope');
});

test('the scope of the page shown comes from the shell, for its repository or another one', () => {
    const doc = shell({
        'data-workbench-server-identity': SERVER + ':session',
        'data-workbench-server-user': 'ada',
        'data-workbench-repository-id': 'lmdb'
    });
    assert.deepEqual(workspace.currentScope(doc), { digest: SERVER, user: 'ada', repositoryId: 'lmdb' });
    assert.deepEqual(workspace.currentScope(doc, 'memory'), { digest: SERVER, user: 'ada', repositoryId: 'memory' });
    assert.deepEqual(workspace.currentScope(shell({ 'data-workbench-server-identity': SERVER }), 'r'),
        { digest: SERVER, user: '', repositoryId: 'r' }, 'no user attribute is anonymous use');
    assert.equal(workspace.currentScope({ getElementById: () => null }), null);
});

test('a scope key can be read back, so a repository\'s keys can be found again', () => {
    const scope = { digest: SERVER, user: 'a"da', repositoryId: 'my repo' };
    const key = workspace.scopeKey('prefix:', scope);
    assert.equal(key, 'prefix:' + JSON.stringify([SERVER, 'a"da', 'my repo']));
    assert.deepEqual(workspace.parseScopeKey('prefix:', key), scope);
    assert.equal(workspace.parseScopeKey('other:', key), null);
    assert.equal(workspace.parseScopeKey('prefix:', 'prefix:{broken'), null);
    assert.equal(workspace.parseScopeKey('prefix:', 'prefix:["a","b"]'), null);
});

test('the saved results query tabs refer to are found in the latest tab states and this page\'s copies', () => {
    const storage = (entries) => {
        const values = new Map(Object.entries(entries));
        return { get length() { return values.size; }, key: (index) => [...values.keys()][index] || null,
            getItem: (key) => (values.has(key) ? values.get(key) : null) };
    };
    const state = (...ids) => JSON.stringify({ activeId: 't0', tabs: ids.map((id, index) => ({ id: 't' + index,
        query: 'ASK {}', lastRun: id ? { status: 'done', saved: { storeId: id, rows: 1 } } : null })) });
    const key = (repository) => workspace.QUERY_TABS_PREFIX + JSON.stringify([SERVER, '', repository]);
    const local = storage({ [key('a')]: state('rows-1', null), [key('b')]: '{broken', other: state('rows-x') });
    const session = storage({ [key('a')]: state('rows-2') });
    assert.deepEqual(workspace.referencedRowStores(local, session), { 'rows-1': true, 'rows-2': true });
    const failing = { get length() { throw new Error('denied'); } };
    assert.equal(workspace.referencedRowStores(failing, session), null);
});
